                return json.loads(resp.read())
        except HTTPError as e:
            body=e.read().decode(errors='replace')
            if e.code == 401 and auth and not refreshed:
                token=None; refreshed=True; continue
            if e.code == 429:
                time.sleep(wait_seconds(e,body)); continue
